Method.Implementation:
	try{
     set sourceSystem=pRequest.SourceSystem
	//Get the connection
	do ..getConnection()
	//set the commit false
	$$$TRACE("AutoCommit:"_..connection.getAutoCommit())
	do ..connection.setAutoCommit(0)
    //Move the cursor    
    if sourceSystem="OR"{
      do ..insertOracleHrToLdapTable(pRequest)
    }elseif (sourceSystem="CO") || (sourceSystem="CA") {
      do ..insertCactusOrCorpprvToLdapTable(pRequest)
    }
      //comiit the transaction
      do ..connection.close()
	  //Close the gateway
	  do ..gateway.%Disconnect()
	  $$$TRACE("After Inser close 3")	
	  set tsc =1
	} CATCH {
		$$$TRACE("Inside Catch111")
		do ..connection.rollback()
		do ..connection.close()
	   //Close the gateway
	   do ..gateway.%Disconnect()	   
	   set tsc = $$$ERROR("Error while inserting data to database")	    	  
	}
	quit tsc


	  do ..createQueryStatement(pRequest)
      // Execute mspr query
      set ..msprInfoRs = ..msprInfoStmt.executeQuery()
      $$$TRACE("After query Execution1")
      //Execute the Mspr Provider Afflication query
      set ..msprAffRs = ..msprProviderAfflicationStmt.executeQuery()
      $$$TRACE("After query Execution")
	  do ..msprInfoRs.moveToInsertRow()	
	  $$$TRACE("After Info ResultSet")  
      do ..msprAffRs.moveToInsertRow() 
      $$$TRACE("After Insert Roew move")
      //Set the parameters
      do ..setMsprInfoValues(pRequest.ldapTableValues.MSPRINFO)    
      $$$TRACE("After Setting value ")
      //Insert the row    
      do ..msprInfoRs.insertRow()
      //Clear the result set
      do ..msprInfoRs.close()
      //set the parameter for affliation table
      do ..setMsprAffliationValues(pRequest.ldapTableValues.MSPRAFFLIATION)
      $$$TRACE("After Inser close 1")
      //Inser the affliation
      do ..msprAffRs.insertRow()
        $$$TRACE("After Inser close 2")
      //Close the result set
      do ..msprAffRs.close()        
      //Commit the connection
      $$$TRACE("After Inser close 3")

	   do ..createQueryStatement(pRequest)
       // Execute mspr query
       set ..msprInfoRs = ..msprInfoStmt.executeQuery()
       $$$TRACE("After query Execution1")       
	   do ..msprInfoRs.moveToInsertRow()	         
       $$$TRACE("After Insert Roew move")
       //Set the parameters
       do ..setMsprInfoValues(pRequest.ldapTableValues.MSPRINFO)    
       $$$TRACE("After Setting value ")
       //Insert the row    
       do ..msprInfoRs.insertRow()
       //Clear the result set
       do ..msprInfoRs.close()
       $$$TRACE("After Insert")
       set affiationList= pRequest.ldapTableValues.MsprAffliationList
       $$$TRACE("List count:"_affiationList.Count())
       FOR i=1:1:affiationList.Count(){
	       $$$TRACE("Inside Loop")
	       set affobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRPRAFFLIATION).%New()
           set affobj = affiationList.GetAt(i) 	                         
           //Execute the Mspr Provider Afflication query
           set ..msprAffRs = ..msprProviderAfflicationStmt.executeQuery()
           $$$TRACE("After query Execution")
           //Store affliation table
           do ..msprAffRs.moveToInsertRow() 
          //set the parameter for affliation table
           do ..setMsprAffliationValues(affobj)
          $$$TRACE("After Inser close 1")
          //Inser the affliation
          do ..msprAffRs.insertRow()
          //Close the result set
          do ..msprAffRs.close()        
          //Commit the connection
          $$$TRACE("After Inser close 2")
       }
       set specialTyList= pRequest.ldapTableValues.MsprSpecialtyList
       $$$TRACE("specialTyList count:"_specialTyList.Count())
       FOR i=1:1:specialTyList.Count(){
	       $$$TRACE("Inside Loop")
	       set specialTyobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRSPECIALTY).%New()
           set specialTyobj = specialTyList.GetAt(i) 	                         
           //Execute the Mspr Provider Afflication query
           set ..msprSpecialTyRs = ..msprSpecialTystmt.executeQuery()
           $$$TRACE("After Speciality query Execution")
           //Store affliation table
           do ..msprSpecialTyRs.moveToInsertRow() 
          //set the parameter for affliation table
           do ..setMsprSpecialtyValues(specialTyobj)
          $$$TRACE("After Inser close 1")
          //Inser the affliation
          do ..msprSpecialTyRs.insertRow()
          //Close the result set
          do ..msprSpecialTyRs.close()        
          //Commit the connection
          $$$TRACE("After Specialty close 2")
       }

	   do ..createQueryStatement(pRequest)
       // Execute mspr query
       set ..msprInfoRs = ..msprInfoStmt.executeQuery()
       $$$TRACE("After query Execution1")       
	   do ..msprInfoRs.moveToInsertRow()	         
